CREATE OR REPLACE FUNCTION public.v221_nonempty(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ BEGIN IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN RETURN false; END IF; IF jsonb_typeof(v)='array' THEN RETURN EXISTS(SELECT 1 FROM jsonb_array_elements(v) x WHERE public.v221_nonempty(x)); END IF; IF jsonb_typeof(v)='object' THEN RETURN EXISTS(SELECT 1 FROM jsonb_each(v) x WHERE public.v221_nonempty(x.value)); END IF; RETURN true; END $$;
CREATE OR REPLACE FUNCTION public.v221_map(r jsonb,d jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE result jsonb; textparts text[]; k text; BEGIN IF jsonb_typeof(r)='string' THEN k=r#>>'{}'; IF left(k,1)='$' THEN RETURN coalesce(d->substr(k,2),'""'::jsonb); END IF; RETURN r; END IF; IF jsonb_typeof(r) IS DISTINCT FROM 'object' THEN RETURN r; END IF; IF r ? 'each' THEN SELECT coalesce(jsonb_agg(public.v221_map(r->'map',x)),'[]') INTO result FROM jsonb_array_elements(coalesce(d->(r->>'each'),'[]')) x; RETURN result; END IF; IF r ? 'joinPath' THEN SELECT array_agg(x#>>'{}') FILTER (WHERE x#>>'{}'<>'') INTO textparts FROM jsonb_array_elements(coalesce(d->(r->>'joinPath'),'[]')) x; RETURN to_jsonb(coalesce(array_to_string(textparts,r->>'separator'),'')); END IF; IF r ? 'join' THEN SELECT array_agg(public.v221_map(x,d)#>>'{}') FILTER (WHERE public.v221_map(x,d)#>>'{}'<>'') INTO textparts FROM jsonb_array_elements(r->'join') x; RETURN to_jsonb(coalesce(array_to_string(textparts,r->>'separator'),'')); END IF; SELECT coalesce(jsonb_object_agg(key,public.v221_map(value,d)),'{}') INTO result FROM jsonb_each(r); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.v221_convert_native(kind text,c jsonb,ctx jsonb,rules jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$
DECLARE mods jsonb:='[]'; issues jsonb:='[]'; h jsonb:=coalesce(c->'hiddenSections','[]'); source jsonb:=coalesce(c->'elementLayout',c->'sourceLayout'); media jsonb:=coalesce(c->'heroMedia','{}'); m jsonb; dat jsonb; v jsonb; k text; size text; fmt text; status text; idx int; path text; item record;
BEGIN
IF EXISTS(SELECT 1 FROM jsonb_each(ctx) WHERE key IN ('eventId','event','eventKey','kitId','brandKitId','calendarId') AND public.v221_nonempty(value)) OR coalesce(ctx->>'sourceLibrary','') ~* '^(san-juan-bowl|sjb|next|event|brand-kit|social-calendar)(-|$)' THEN RETURN jsonb_build_object('version','v221-content-1','status','excluded','layout',null,'issues','[]'::jsonb,'basis','out_of_scope'); END IF;
IF source ? 'modules' THEN RETURN jsonb_build_object('version','v221-content-1','status','clean','layout',source,'issues','[]'::jsonb,'basis','existing_v221'); END IF;
IF public.v221_nonempty(c->'original') THEN RETURN jsonb_build_object('version','v221-content-1','status','failed','layout',null,'issues',jsonb_build_array(jsonb_build_object('path','content.original','construct','absolute-position text/runs, vector shapes and image geometry have no module-stack mapping')),'basis','original_geometry'); END IF;
IF public.v221_nonempty(c->'pages') THEN RETURN jsonb_build_object('version','v221-content-1','status','failed','layout',null,'issues',jsonb_build_array(jsonb_build_object('path','content.pages','construct','multi-page proposal page kinds and positioned content are not mapped')),'basis','native'); END IF;
IF NOT h ? 'masthead' THEN dat=jsonb_build_object('title',CASE WHEN kind='case-study' THEN coalesce(nullif(c->>'summary',''),nullif(c->>'title',''),c->>'client','') ELSE coalesce(nullif(c->>'title',''),nullif(c->>'productName',''),c->>'partner','') END,'lead',CASE WHEN kind='case-study' THEN concat_ws(' · ',nullif(c->>'industry',''),nullif(c->>'audience','')) ELSE concat_ws(E'\n',nullif(c->>'tagline',''),nullif(c->>'summary','')) END,'eyebrow',coalesce(c->>'eyebrow',''),'photo',CASE WHEN h ? 'hero' THEN 'null'::jsonb ELSE coalesce(media->'imageUrl','null') END,'layout',CASE WHEN NOT h ? 'hero' AND public.v221_nonempty(media->'imageUrl') THEN 'full' ELSE 'text' END); mods=mods||jsonb_build_array(jsonb_build_object('type','hero','data',dat)); END IF;
IF kind='case-study' AND NOT h ? 'story' THEN SELECT coalesce(jsonb_agg(x),'[]') INTO v FROM jsonb_array_elements(jsonb_build_array(c->'challenge',c->'solution',c->'result')) x WHERE public.v221_nonempty(x); mods=mods||jsonb_build_array(public.v221_map(rules->'narrative',jsonb_build_object('items',v))); END IF;
IF kind='ebrochure' AND NOT h ? 'sections' THEN mods=mods||jsonb_build_array(public.v221_map(rules->'narrative',jsonb_build_object('items',coalesce(c->'sections','[]')))); END IF;
IF kind='spotlight' AND NOT h ? 'capabilities' THEN SELECT coalesce(jsonb_agg(jsonb_build_object('title',coalesce(x->>'heading',''),'text',coalesce(x->>'body',''))),'[]') INTO v FROM jsonb_array_elements(coalesce(c->'capabilities','[]')) x; mods=mods||jsonb_build_array(jsonb_build_object('type','capabilities','data',jsonb_build_object('items',v))); END IF;
IF NOT h ? 'stats' THEN mods=mods||jsonb_build_array(public.v221_map(rules->'stats',jsonb_build_object('items',coalesce(c->'stats','[]')))); END IF;
IF NOT h ? 'quote' THEN mods=mods||jsonb_build_array(public.v221_map(rules->'quote',coalesce(c->'quote','{}'))); END IF;
IF NOT h ? 'engagement' THEN dat=jsonb_build_object('title',coalesce(c#>>'{engagement,title}',''),'items',coalesce(public.v221_map('{"joinPath":"bullets","separator":"\n"}',coalesce(c->'engagement','{}')),'""')); mods=mods||jsonb_build_array(jsonb_build_object('type','checklist','data',dat)); END IF;
IF NOT h ? 'discover' AND public.v221_nonempty(c->'discover') THEN mods=mods||jsonb_build_array(public.v221_map(rules->'narrative',jsonb_build_object('items',jsonb_build_array(jsonb_build_object('heading','','body',c#>'{discover,body}','bullets',coalesce(c#>'{discover,bullets}','[]')))))); END IF;
IF NOT h ? 'expert' AND public.v221_nonempty(c->'expert') THEN mods=mods||jsonb_build_array(public.v221_map(rules->'contact',c->'expert')); END IF;
FOR m,idx IN SELECT value,(ordinality-1)::int FROM jsonb_array_elements(coalesce(c->'modules','[]')) WITH ORDINALITY LOOP
IF h ? coalesce(m->>'id','') THEN CONTINUE; END IF; path='content.modules['||idx||']'; IF rules ? (m->>'kind') THEN mods=mods||jsonb_build_array(public.v221_map(rules->(m->>'kind'),m)); ELSE issues=issues||jsonb_build_array(jsonb_build_object('path',path,'construct','unsupported native module: '||coalesce(m->>'kind',''))); END IF;
FOREACH k IN ARRAY ARRAY['variantId','sectionLayoutId','rule','titleType','adjust','meta','stats','quote','partner','partnerLogoUrl','orgLogoUrl','heightPct','rows','path','deviceTone'] LOOP IF public.v221_nonempty(m->k) THEN issues=issues||jsonb_build_array(jsonb_build_object('path',path||'.'||k,'construct',CASE WHEN k='variantId' THEN 'native geometry variant: '||(m->>k) ELSE 'native module '||k||' not preserved by mapping' END)); END IF; END LOOP;
IF m->>'kind'='table' THEN issues=issues||jsonb_build_array(jsonb_build_object('path',path,'construct','table converted to labelled rows, not equivalent table semantics')); END IF; END LOOP;
IF NOT h ? 'cta' THEN dat=jsonb_build_object('title',coalesce(c#>>'{cta,label}',''),'sub',coalesce(c#>>'{cta,subhead}',''),'button',coalesce(c#>>'{cta,buttonLabel}',''),'link',coalesce(c#>>'{cta,url}','')); mods=mods||jsonb_build_array(jsonb_build_object('type','cta','data',dat)); END IF;
IF NOT h ? 'footer' THEN dat=jsonb_build_object('extra',public.v221_map('{"joinPath":"links","separator":"\n"}',coalesce(c->'footer','{}'))); mods=mods||jsonb_build_array(jsonb_build_object('type','footer','data',dat)); END IF;
FOR item IN SELECT * FROM jsonb_each(c) LOOP IF item.key<>ALL(ARRAY['title','client','summary','eyebrow','industry','audience','tagline','productName','challenge','solution','result','sections','capabilities','features','knowHow','stats','quote','engagement','discover','expert','modules','cta','footer','hiddenSections','heroMedia']) AND public.v221_nonempty(item.value) THEN issues=issues||jsonb_build_array(jsonb_build_object('path','content.'||item.key,'construct','unmapped native construct')); END IF; END LOOP;
IF NOT h ? 'hero' THEN FOR item IN SELECT * FROM jsonb_each(media) LOOP IF item.key<>'imageUrl' AND public.v221_nonempty(item.value) THEN issues=issues||jsonb_build_array(jsonb_build_object('path','content.heroMedia.'||item.key,'construct','native photo crop/treatment not mapped')); END IF; END LOOP; END IF;
FOR item IN SELECT * FROM jsonb_each(ctx) LOOP IF item.key<>ALL(ARRAY['pageSize','sourceLibrary','libraryItemId','sourceSlug','sourceFile','collection','divisionId','siblingDeckId','createdBy','distribution','starterTemplateId','blankStart','importReview','contactCard','exportPrefs']) AND public.v221_nonempty(item.value) THEN issues=issues||jsonb_build_array(jsonb_build_object('path','context.'||item.key,'construct','native editor/layout setting not mapped')); END IF; END LOOP;
size=coalesce(ctx#>>'{exportPrefs,size}',ctx->>'pageSize','Letter'); fmt=CASE size WHEN 'A4' THEN 'a4' WHEN 'Letter' THEN 'letter' WHEN 'Square' THEN 'square' END; IF fmt IS NULL THEN issues=issues||jsonb_build_array(jsonb_build_object('path','context.pageSize','construct','unsupported native format: '||size)); END IF;
SELECT coalesce(jsonb_agg(x||jsonb_build_object('id','converted-'||(ordinality-1))),'[]') INTO mods FROM (SELECT value x,row_number() OVER () ordinality FROM jsonb_array_elements(mods) WHERE public.v221_nonempty(value->'data')) t;
status=CASE WHEN jsonb_array_length(mods)=0 THEN 'failed' WHEN jsonb_array_length(issues)>0 THEN 'partial' ELSE 'clean' END;
RETURN jsonb_build_object('version','v221-content-1','status',status,'layout',CASE WHEN status='failed' THEN null ELSE jsonb_build_object('format',coalesce(fmt,'letter'),'modules',mods) END,'issues',issues,'basis','native'); END $$;
REVOKE ALL ON FUNCTION public.v221_nonempty(jsonb),public.v221_map(jsonb,jsonb),public.v221_convert_native(text,jsonb,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.v221_nonempty(jsonb),public.v221_map(jsonb,jsonb),public.v221_convert_native(text,jsonb,jsonb,jsonb) TO service_role;